import { z } from 'zod';

// Standalone email configuration (@proxypilot/email). Same contract as the auth
// module: the module carries no dependency on any host config.ts — the host
// injects a resolved EmailConfig once via initEmail({ db, config }), built
// either in code (resolveEmailConfig) or from the environment
// (loadEmailConfigFromEnv).
//
// Environment config is the BASELINE; an admin-saved connection row
// (email_connections, status 'configured'/'verified') OVERRIDES it at send
// time — so an operator can point the app at Resend or any SMTP server from
// the admin UI without redeploying. See service.ts resolveSendConfig().

export const EMAIL_PROVIDERS = ['resend', 'smtp', 'console'] as const;
export type EmailProvider = (typeof EMAIL_PROVIDERS)[number];

export const SMTP_SECURITY_MODES = ['implicit', 'starttls', 'none'] as const;
export type SmtpSecurity = (typeof SMTP_SECURITY_MODES)[number];

export const EmailConfigSchema = z.object({
  NODE_ENV: z.string().default('development'),

  // Which transport sends mail when NO admin-configured connection row exists.
  // 'console' (the default) logs the message server-side and records it in
  // email_log — the app boots and works before any provider is configured.
  EMAIL_PROVIDER: z.enum(EMAIL_PROVIDERS).default('console'),

  // Envelope/header sender. Resend requires a verified domain/sender; SMTP
  // servers typically enforce an allowed From. "Name <addr>" is built from the
  // pair at send time.
  EMAIL_FROM: z.string().default(''),
  EMAIL_FROM_NAME: z.string().default(''),

  // Resend (EMAIL_PROVIDER=resend): the API key. Prefer configuring via the
  // admin UI (encrypted at rest) — the env var is for infra-managed setups.
  RESEND_API_KEY: z.string().default(''),

  // Generic SMTP (EMAIL_PROVIDER=smtp): host/port/security/credentials.
  // 'implicit' = TLS from byte one (typically :465); 'starttls' = plaintext
  // upgrade (typically :587, the default); 'none' = unencrypted (local relays
  // only — never across the internet).
  SMTP_HOST: z.string().default(''),
  SMTP_PORT: z.coerce.number().int().positive().max(65535).default(587),
  SMTP_SECURITY: z.enum(SMTP_SECURITY_MODES).default('starttls'),
  SMTP_USERNAME: z.string().default(''),
  SMTP_PASSWORD: z.string().default(''),

  // Derives the AES-256-GCM key encrypting the stored provider secret (SMTP
  // password / Resend key) — same pattern as the auth module's master secret.
  // Production MUST inject a real value from a secrets manager.
  EMAIL_MASTER_SECRET: z.string().default('dev-insecure-email-master-secret-change-me'),

  // Per-attempt network timeout for a send (SMTP dialogue or Resend HTTPS call).
  EMAIL_SEND_TIMEOUT_MS: z.coerce.number().int().positive().default(20000),
});

export type EmailConfig = z.infer<typeof EmailConfigSchema>;
export type EmailConfigInput = Partial<Record<keyof EmailConfig, unknown>>;

// Build a fully-resolved EmailConfig from a partial object (defaults applied).
export function resolveEmailConfig(input: EmailConfigInput = {}): EmailConfig {
  return EmailConfigSchema.parse(input);
}

// Build an EmailConfig from environment variables (defaults applied).
export function loadEmailConfigFromEnv(env: NodeJS.ProcessEnv = process.env): EmailConfig {
  return EmailConfigSchema.parse({
    NODE_ENV: env.NODE_ENV,
    EMAIL_PROVIDER: env.EMAIL_PROVIDER,
    EMAIL_FROM: env.EMAIL_FROM,
    EMAIL_FROM_NAME: env.EMAIL_FROM_NAME,
    RESEND_API_KEY: env.RESEND_API_KEY,
    SMTP_HOST: env.SMTP_HOST,
    SMTP_PORT: env.SMTP_PORT,
    SMTP_SECURITY: env.SMTP_SECURITY,
    SMTP_USERNAME: env.SMTP_USERNAME,
    SMTP_PASSWORD: env.SMTP_PASSWORD,
    EMAIL_MASTER_SECRET: env.EMAIL_MASTER_SECRET,
    EMAIL_SEND_TIMEOUT_MS: env.EMAIL_SEND_TIMEOUT_MS,
  });
}

import type { NodePgDatabase } from 'drizzle-orm/node-postgres';
import type { EmailConfig } from './config.js';

// Dependency-injection context for the reusable email module — identical shape
// to the auth module's: the host injects its Drizzle client + resolved config
// once at boot via initEmail(); `db`/`config` proxies forward every access to
// the injected instances so module files import them by name.

export type EmailDb = NodePgDatabase<Record<string, never>>;

interface EmailRuntime {
  db: EmailDb;
  config: EmailConfig;
}

let runtime: EmailRuntime | null = null;

export interface InitEmailOptions {
  db: EmailDb;
  config: EmailConfig;
}

// Inject the host's Drizzle client + resolved config. Call once at boot,
// BEFORE mounting the router / sending mail. Calling again replaces the
// runtime (test helper).
export function initEmail(opts: InitEmailOptions): void {
  runtime = { db: opts.db, config: opts.config };
}

export function isEmailInitialized(): boolean {
  return runtime !== null;
}

export function resetEmailContext(): void {
  runtime = null;
}

function requireRuntime(): EmailRuntime {
  if (!runtime) {
    throw new Error(
      '@proxypilot/email: not initialized — call initEmail({ db, config }) at boot before using the email module.',
    );
  }
  return runtime;
}

export function getDb(): EmailDb {
  return requireRuntime().db;
}

export function getConfig(): EmailConfig {
  return requireRuntime().config;
}

export const db: EmailDb = new Proxy({} as EmailDb, {
  get(_target, prop, receiver) {
    const real = getDb() as unknown as Record<string | symbol, unknown>;
    const value = Reflect.get(real, prop, receiver);
    return typeof value === 'function' ? (value as (...a: unknown[]) => unknown).bind(real) : value;
  },
});

export const config: EmailConfig = new Proxy({} as EmailConfig, {
  get(_target, prop, receiver) {
    const real = getConfig() as unknown as Record<string | symbol, unknown>;
    return Reflect.get(real, prop, receiver);
  },
});

import crypto from 'node:crypto';

// Secret storage for the email module: AES-256-GCM over Node's built-in
// crypto — the exact scheme the auth module uses for LDAPS settings, so an
// operator reasons about one posture. The key derives from EMAIL_MASTER_SECRET
// (scrypt, static salt: this is key STRETCHING of an injected secret, not
// password storage) and the nonce is random per encryption.

const KEYLEN = 32;
const SALT = 'proxypilot-email-secret-v1';

function deriveKey(masterSecret: string): Buffer {
  return crypto.scryptSync(masterSecret, SALT, KEYLEN);
}

export function encryptSecret(plaintext: string, masterSecret: string): {
  ciphertext: string;
  nonce: string;
} {
  const key = deriveKey(masterSecret);
  const nonce = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, nonce);
  const enc = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return {
    ciphertext: Buffer.concat([enc, tag]).toString('base64'),
    nonce: nonce.toString('base64'),
  };
}

export function decryptSecret(ciphertextB64: string, nonceB64: string, masterSecret: string): string {
  const key = deriveKey(masterSecret);
  const data = Buffer.from(ciphertextB64, 'base64');
  const nonce = Buffer.from(nonceB64, 'base64');
  const tag = data.subarray(data.length - 16);
  const enc = data.subarray(0, data.length - 16);
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, nonce);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(enc), decipher.final()]).toString('utf8');
}

import { desc, eq } from 'drizzle-orm';
import { db } from './context.js';
import { emailConnections, emailLog } from './schema.js';

// Data access for the email module. Drizzle only.

export type EmailConnectionRow = typeof emailConnections.$inferSelect;
export type EmailLogRow = typeof emailLog.$inferSelect;

export async function getConnection(tenantId = 'default'): Promise<EmailConnectionRow | null> {
  const rows = await db.select().from(emailConnections).where(eq(emailConnections.tenantId, tenantId)).limit(1);
  return rows[0] ?? null;
}

export async function upsertConnection(input: {
  tenantId?: string;
  provider: string;
  fromEmail: string;
  fromName: string;
  smtpHost: string;
  smtpPort: number;
  smtpSecurity: string;
  smtpUsername: string;
  // null → keep the stored secret; '' → clear it; value → re-encrypt.
  secretCiphertext: string | null;
  secretNonce: string | null;
  status: string;
}): Promise<EmailConnectionRow> {
  const tenantId = input.tenantId ?? 'default';
  const existing = await getConnection(tenantId);
  const secretPatch = input.secretCiphertext === null
    ? {}
    : { secretCiphertext: input.secretCiphertext, secretNonce: input.secretNonce ?? '' };
  if (existing) {
    await db.update(emailConnections)
      .set({
        provider: input.provider,
        fromEmail: input.fromEmail,
        fromName: input.fromName,
        smtpHost: input.smtpHost,
        smtpPort: input.smtpPort,
        smtpSecurity: input.smtpSecurity,
        smtpUsername: input.smtpUsername,
        ...secretPatch,
        status: input.status,
        updatedAt: new Date(),
      })
      .where(eq(emailConnections.id, existing.id));
    return (await getConnection(tenantId))!;
  }
  await db.insert(emailConnections).values({
    tenantId,
    provider: input.provider,
    fromEmail: input.fromEmail,
    fromName: input.fromName,
    smtpHost: input.smtpHost,
    smtpPort: input.smtpPort,
    smtpSecurity: input.smtpSecurity,
    smtpUsername: input.smtpUsername,
    secretCiphertext: input.secretCiphertext ?? '',
    secretNonce: input.secretNonce ?? '',
    status: input.status,
  });
  return (await getConnection(tenantId))!;
}

export async function setConnectionTestResult(tenantId: string, ok: boolean, error: string | null): Promise<void> {
  const existing = await getConnection(tenantId);
  if (!existing) return;
  await db.update(emailConnections)
    .set({ status: ok ? 'verified' : 'failed', lastTestAt: new Date(), lastTestError: error, updatedAt: new Date() })
    .where(eq(emailConnections.id, existing.id));
}

export async function insertLog(input: {
  tenantId?: string;
  toEmail: string;
  subject: string;
  provider: string;
  status: 'sent' | 'failed';
  error?: string | null;
  messageId?: string | null;
}): Promise<void> {
  await db.insert(emailLog).values({
    tenantId: input.tenantId ?? 'default',
    toEmail: input.toEmail,
    subject: input.subject.slice(0, 300),
    provider: input.provider,
    status: input.status,
    error: input.error ?? null,
    messageId: input.messageId ?? null,
  });
}

export async function listLog(tenantId = 'default', limit = 100): Promise<EmailLogRow[]> {
  return db.select().from(emailLog)
    .where(eq(emailLog.tenantId, tenantId))
    .orderBy(desc(emailLog.id))
    .limit(Math.min(500, Math.max(1, limit)));
}

import crypto from 'node:crypto';

// Minimal, dependency-free RFC 5322 message building — enough for
// transactional email (text and/or HTML, one From, multiple To, optional
// Reply-To). Bodies are base64-encoded (dodges line-length and 8-bit issues
// everywhere); headers with non-ASCII are RFC 2047 B-encoded. Pure functions —
// unit-tested without a socket.

export interface MailInput {
  from: string;        // "Name <addr>" or bare addr
  to: string[];        // bare addresses (or "Name <addr>")
  subject: string;
  text?: string;
  html?: string;
  replyTo?: string;
}

// Extract the bare addr-spec from "Name <addr>" (already-bare input passes
// through). The SMTP envelope (MAIL FROM/RCPT TO) needs bare addresses.
export function bareAddress(value: string): string {
  const m = /<([^<>\s]+@[^<>\s]+)>/.exec(String(value || ''));
  if (m) return m[1]!;
  return String(value || '').trim();
}

const ADDR_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
export function isEmailAddress(value: string): boolean {
  return ADDR_RE.test(bareAddress(value));
}

// RFC 2047 B-encode a header value when it carries non-ASCII; pass through
// otherwise. Also strips CR/LF (header-injection defense — user-influenced
// subjects must never smuggle extra headers).
export function encodeHeaderValue(value: string): string {
  const clean = String(value || '').replace(/[\r\n]+/g, ' ');
  if (/^[\x20-\x7e]*$/.test(clean)) return clean;
  return `=?UTF-8?B?${Buffer.from(clean, 'utf8').toString('base64')}?=`;
}

function base64Lines(content: string): string {
  const b64 = Buffer.from(content, 'utf8').toString('base64');
  return b64.replace(/(.{76})/g, '$1\r\n');
}

// Build the full RFC 5322 message (headers + body), CRLF line endings.
// text+html → multipart/alternative (text first, html last: last part wins in
// capable clients); one of them → a single part. Returns the message and its
// Message-ID (also recorded in email_log).
export function buildMimeMessage(input: MailInput, opts: { hostname?: string; date?: Date } = {}): {
  message: string;
  messageId: string;
} {
  const host = (opts.hostname || bareAddress(input.from).split('@')[1] || 'localhost').trim();
  const messageId = `<${crypto.randomUUID()}@${host}>`;
  const date = (opts.date || new Date()).toUTCString().replace('GMT', '+0000');

  const headers: string[] = [
    `From: ${encodeHeaderValue(input.from)}`,
    `To: ${input.to.map((t) => encodeHeaderValue(t)).join(', ')}`,
    `Subject: ${encodeHeaderValue(input.subject)}`,
    `Date: ${date}`,
    `Message-ID: ${messageId}`,
    'MIME-Version: 1.0',
  ];
  if (input.replyTo) headers.push(`Reply-To: ${encodeHeaderValue(input.replyTo)}`);

  const text = input.text ?? '';
  const html = input.html ?? '';
  let body: string;
  if (text && html) {
    const boundary = `=_pp_${crypto.randomBytes(12).toString('hex')}`;
    headers.push(`Content-Type: multipart/alternative; boundary="${boundary}"`);
    body = [
      `--${boundary}`,
      'Content-Type: text/plain; charset=utf-8',
      'Content-Transfer-Encoding: base64',
      '',
      base64Lines(text),
      `--${boundary}`,
      'Content-Type: text/html; charset=utf-8',
      'Content-Transfer-Encoding: base64',
      '',
      base64Lines(html),
      `--${boundary}--`,
      '',
    ].join('\r\n');
  } else {
    headers.push(`Content-Type: ${html ? 'text/html' : 'text/plain'}; charset=utf-8`);
    headers.push('Content-Transfer-Encoding: base64');
    body = `${base64Lines(html || text)}\r\n`;
  }

  return { message: `${headers.join('\r\n')}\r\n\r\n${body}`, messageId };
}

// SMTP DATA dot-stuffing (RFC 5321 §4.5.2): a line starting with '.' gets a
// second '.' so the bare ".\r\n" terminator can't be forged by content.
export function dotStuff(message: string): string {
  return message.replace(/\r\n\./g, '\r\n..').replace(/^\./, '..');
}

import net from 'node:net';
import tls from 'node:tls';
import type { SmtpSecurity } from './config.js';
import { dotStuff } from './mime.js';

// Minimal, dependency-free SMTP submission client (RFC 5321) on Node's built-in
// net/tls — the same "audited built-ins over native deps" posture as the auth
// module's crypto. Supports the three transport modes every mainstream provider
// offers (implicit TLS :465, STARTTLS :587, plaintext for local relays) and
// AUTH PLAIN / AUTH LOGIN. This is a SUBMISSION client for one message to one
// server — not a queueing MTA; retries/backoff belong to the caller.

export interface SmtpConnection {
  host: string;
  port: number;
  security: SmtpSecurity;
  username?: string;
  password?: string;
  timeoutMs?: number;
}

export interface SmtpSendResult {
  ok: true;
  response: string; // the final 250 line — providers put their queue id here
}

export class SmtpError extends Error {
  constructor(message: string, public readonly code: number | null = null) {
    super(message);
    this.name = 'SmtpError';
  }
}

// Parse one (possibly multi-line) SMTP reply from the head of `buffer`.
// Returns null while incomplete; else { code, text, rest }. Multi-line replies
// use "250-..." continuation lines and end at "250 ...". Exported for tests.
export function parseSmtpReply(buffer: string): { code: number; text: string; rest: string } | null {
  const lines: string[] = [];
  let rest = buffer;
  for (;;) {
    const nl = rest.indexOf('\r\n');
    if (nl < 0) return null; // incomplete
    const line = rest.slice(0, nl);
    rest = rest.slice(nl + 2);
    lines.push(line);
    const m = /^(\d{3})([ -])/.exec(line);
    if (!m) return { code: 0, text: lines.join('\n'), rest }; // malformed — surface as code 0
    if (m[2] === ' ') return { code: Number(m[1]), text: lines.join('\n'), rest };
    // '-' → continuation; keep reading
  }
}

interface Dialogue {
  send(line: string | null, expect: number[]): Promise<{ code: number; text: string }>;
  upgradeTls(): Promise<void>;
  end(): void;
}

function openDialogue(conn: SmtpConnection): Promise<Dialogue> {
  const timeoutMs = conn.timeoutMs ?? 20000;
  return new Promise((resolve, reject) => {
    let socket: net.Socket | tls.TLSSocket = conn.security === 'implicit'
      ? tls.connect({ host: conn.host, port: conn.port, servername: conn.host })
      : net.connect({ host: conn.host, port: conn.port });

    let buffer = '';
    let waiter: { expect: number[]; resolve: (r: { code: number; text: string }) => void; reject: (e: Error) => void } | null = null;
    let failed: Error | null = null;

    const fail = (err: Error) => {
      if (failed) return;
      failed = err;
      if (waiter) { waiter.reject(err); waiter = null; }
      socket.destroy();
      reject(err);
    };

    const pump = () => {
      while (waiter) {
        const reply = parseSmtpReply(buffer);
        if (!reply) return;
        buffer = reply.rest;
        const w = waiter;
        waiter = null;
        if (!w.expect.includes(Math.floor(reply.code / 100) * 100) && !w.expect.includes(reply.code)) {
          w.reject(new SmtpError(`SMTP ${reply.code}: ${reply.text.slice(0, 300)}`, reply.code));
        } else {
          w.resolve({ code: reply.code, text: reply.text });
        }
      }
    };

    const wire = (s: net.Socket | tls.TLSSocket) => {
      s.setTimeout(timeoutMs, () => fail(new SmtpError(`SMTP timeout after ${timeoutMs}ms talking to ${conn.host}:${conn.port}`)));
      s.on('data', (chunk) => { buffer += chunk.toString('utf8'); pump(); });
      s.on('error', (err) => fail(new SmtpError(`SMTP connection error: ${(err as Error).message}`)));
      s.on('close', () => fail(new SmtpError('SMTP connection closed unexpectedly')));
    };
    wire(socket);

    const dialogue: Dialogue = {
      send(line, expect) {
        return new Promise((res, rej) => {
          if (failed) return rej(failed);
          waiter = { expect, resolve: res, reject: rej };
          if (line !== null) socket.write(`${line}\r\n`);
          pump(); // a reply may already be buffered (the greeting)
        });
      },
      upgradeTls() {
        return new Promise((res, rej) => {
          const plain = socket as net.Socket;
          plain.removeAllListeners('data');
          plain.removeAllListeners('error');
          plain.removeAllListeners('close');
          plain.setTimeout(0);
          const secure = tls.connect({ socket: plain, servername: conn.host }, () => res());
          secure.once('error', (err) => rej(new SmtpError(`STARTTLS failed: ${err.message}`)));
          buffer = '';
          socket = secure;
          wire(secure);
        });
      },
      end() {
        failed = failed ?? new SmtpError('closed'); // silence the close handler
        socket.destroy();
      },
    };

    // Resolve once connected; the caller drives the dialogue (greeting first).
    socket.once(conn.security === 'implicit' ? 'secureConnect' : 'connect', () => resolve(dialogue));
  });
}

// Send one prepared RFC 5322 message. `from`/`to` are BARE addresses (the
// envelope); the message carries its own headers.
export async function smtpSend(
  conn: SmtpConnection,
  envelope: { from: string; to: string[] },
  message: string,
): Promise<SmtpSendResult> {
  const d = await openDialogue(conn);
  try {
    await d.send(null, [220]); // greeting
    const ehlo = await d.send(`EHLO ${conn.host}`, [250]);

    if (conn.security === 'starttls') {
      if (!/STARTTLS/i.test(ehlo.text)) throw new SmtpError('server does not offer STARTTLS — use security "implicit" (:465) or a different port');
      await d.send('STARTTLS', [220]);
      await d.upgradeTls();
      await d.send(`EHLO ${conn.host}`, [250]);
    }

    if (conn.username) {
      if (conn.security === 'none') throw new SmtpError('refusing to send credentials over an unencrypted connection — use starttls or implicit');
      const plain = Buffer.from(`\0${conn.username}\0${conn.password ?? ''}`, 'utf8').toString('base64');
      try {
        await d.send(`AUTH PLAIN ${plain}`, [235]);
      } catch (err) {
        if (err instanceof SmtpError && (err.code === 504 || err.code === 500 || err.code === 502)) {
          // Server without AUTH PLAIN — fall back to AUTH LOGIN.
          await d.send('AUTH LOGIN', [334]);
          await d.send(Buffer.from(conn.username, 'utf8').toString('base64'), [334]);
          await d.send(Buffer.from(conn.password ?? '', 'utf8').toString('base64'), [235]);
        } else {
          throw err;
        }
      }
    }

    await d.send(`MAIL FROM:<${envelope.from}>`, [250]);
    for (const rcpt of envelope.to) {
      await d.send(`RCPT TO:<${rcpt}>`, [250, 251]);
    }
    await d.send('DATA', [354]);
    const final = await d.send(`${dotStuff(message)}\r\n.`, [250]);
    // QUIT politely but never let it fail the send.
    try { await d.send('QUIT', [221]); } catch { /* sent successfully regardless */ }
    return { ok: true, response: final.text };
  } finally {
    d.end();
  }
}

// Resend driver — the HTTPS API (https://resend.com), no SDK dependency: one
// POST to /emails with a Bearer key. Resend is the recommended provider for
// generated apps (single API key, no SMTP dance), but the module treats it as
// exactly one driver among equals — see smtp-client.ts for everything else.

export interface ResendSendInput {
  apiKey: string;
  from: string;         // "Name <addr>" — the domain must be verified in Resend
  to: string[];
  subject: string;
  text?: string;
  html?: string;
  replyTo?: string;
  timeoutMs?: number;
}

export interface ResendSendResult {
  ok: true;
  id: string; // Resend message id
}

export async function resendSend(input: ResendSendInput): Promise<ResendSendResult> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), input.timeoutMs ?? 20000);
  try {
    const res = await fetch('https://api.resend.com/emails', {
      method: 'POST',
      headers: {
        authorization: `Bearer ${input.apiKey}`,
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        from: input.from,
        to: input.to,
        subject: input.subject,
        ...(input.text ? { text: input.text } : {}),
        ...(input.html ? { html: input.html } : {}),
        ...(input.replyTo ? { reply_to: input.replyTo } : {}),
      }),
      signal: controller.signal,
    });
    const body = await res.text();
    if (!res.ok) {
      let detail = body.slice(0, 300);
      try {
        const j = JSON.parse(body) as { message?: string; name?: string };
        if (j.message) detail = `${j.name ? `${j.name}: ` : ''}${j.message}`;
      } catch { /* keep raw */ }
      throw new Error(`Resend HTTP ${res.status}: ${detail}`);
    }
    let id = '';
    try { id = String((JSON.parse(body) as { id?: string }).id || ''); } catch { /* tolerate */ }
    return { ok: true, id };
  } catch (err) {
    if ((err as Error).name === 'AbortError') {
      throw new Error(`Resend request timed out after ${input.timeoutMs ?? 20000}ms`);
    }
    throw err;
  } finally {
    clearTimeout(timer);
  }
}

import { config } from './context.js';
import type { EmailProvider, SmtpSecurity } from './config.js';
import { decryptSecret } from './crypto.js';
import { buildMimeMessage, bareAddress, isEmailAddress } from './mime.js';
import { smtpSend } from './smtp-client.js';
import { resendSend } from './resend-client.js';
import { getConnection, insertLog, setConnectionTestResult } from './repo.js';

// sendEmail — the module's one job. Resolution order for WHICH provider runs:
//   1. the admin-configured connection row (email_connections) when its status
//      is configured/verified — an operator points the app at Resend or any
//      SMTP server from the admin UI, no redeploy;
//   2. else the injected env config (EMAIL_PROVIDER et al.);
//   3. 'console' logs the message server-side — the app works before setup
//      (verification links land in the server log, called out as such).
// Every attempt lands in email_log (status sent/failed, no bodies).

export interface SendEmailInput {
  to: string | string[];
  subject: string;
  text?: string;
  html?: string;
  replyTo?: string;
  tenantId?: string;
}

export interface SendEmailResult {
  ok: boolean;
  provider: EmailProvider;
  messageId?: string;
  error?: string;
}

interface ResolvedSendConfig {
  provider: EmailProvider;
  from: string;         // display form "Name <addr>" (or bare addr)
  fromAddress: string;  // bare envelope address
  resendApiKey: string;
  smtp: { host: string; port: number; security: SmtpSecurity; username: string; password: string };
}

function displayFrom(fromEmail: string, fromName: string): string {
  return fromName ? `${fromName.replace(/[\r\n<>]+/g, ' ').trim()} <${fromEmail}>` : fromEmail;
}

// Exported for tests and for the admin routes' "what would send right now"
// status readout.
export async function resolveSendConfig(tenantId = 'default'): Promise<ResolvedSendConfig> {
  const conn = await getConnection(tenantId);
  if (conn && ['configured', 'verified'].includes(conn.status)) {
    const secret = conn.secretCiphertext
      ? decryptSecret(conn.secretCiphertext, conn.secretNonce, config.EMAIL_MASTER_SECRET)
      : '';
    return {
      provider: (['resend', 'smtp', 'console'].includes(conn.provider) ? conn.provider : 'console') as EmailProvider,
      from: displayFrom(conn.fromEmail, conn.fromName),
      fromAddress: bareAddress(conn.fromEmail),
      resendApiKey: conn.provider === 'resend' ? secret : '',
      smtp: {
        host: conn.smtpHost,
        port: conn.smtpPort,
        security: (['implicit', 'starttls', 'none'].includes(conn.smtpSecurity) ? conn.smtpSecurity : 'starttls') as SmtpSecurity,
        username: conn.smtpUsername,
        password: conn.provider === 'smtp' ? secret : '',
      },
    };
  }
  return {
    provider: config.EMAIL_PROVIDER,
    from: displayFrom(config.EMAIL_FROM, config.EMAIL_FROM_NAME),
    fromAddress: bareAddress(config.EMAIL_FROM),
    resendApiKey: config.RESEND_API_KEY,
    smtp: {
      host: config.SMTP_HOST,
      port: config.SMTP_PORT,
      security: config.SMTP_SECURITY,
      username: config.SMTP_USERNAME,
      password: config.SMTP_PASSWORD,
    },
  };
}

export async function sendEmail(input: SendEmailInput): Promise<SendEmailResult> {
  const tenantId = input.tenantId ?? 'default';
  const to = (Array.isArray(input.to) ? input.to : [input.to]).map((t) => String(t || '').trim()).filter(Boolean);
  if (!to.length || !to.every(isEmailAddress)) {
    return { ok: false, provider: 'console', error: 'invalid recipient address' };
  }

  const resolved = await resolveSendConfig(tenantId);
  const log = (status: 'sent' | 'failed', error: string | null, messageId: string | null) =>
    insertLog({ tenantId, toEmail: to.join(', '), subject: input.subject, provider: resolved.provider, status, error, messageId })
      .catch(() => { /* the log must never fail a send */ });

  try {
    if (resolved.provider === 'console') {
      // Dev sink: the full message goes to the server log so flows that email
      // links (verification, invites) stay testable before a provider exists.
      // eslint-disable-next-line no-console
      console.log(
        `[email:console] to=${to.join(', ')} subject=${JSON.stringify(input.subject)}\n${input.text || input.html || '(no body)'}`,
      );
      await log('sent', null, null);
      return { ok: true, provider: 'console' };
    }

    if (!resolved.fromAddress || !isEmailAddress(resolved.fromAddress)) {
      throw new Error('no valid From address configured (set EMAIL_FROM or configure the connection in the admin UI)');
    }

    if (resolved.provider === 'resend') {
      if (!resolved.resendApiKey) throw new Error('Resend is selected but no API key is configured');
      const r = await resendSend({
        apiKey: resolved.resendApiKey,
        from: resolved.from,
        to,
        subject: input.subject,
        text: input.text,
        html: input.html,
        replyTo: input.replyTo,
        timeoutMs: config.EMAIL_SEND_TIMEOUT_MS,
      });
      await log('sent', null, r.id);
      return { ok: true, provider: 'resend', messageId: r.id };
    }

    // smtp
    if (!resolved.smtp.host) throw new Error('SMTP is selected but no host is configured');
    const { message, messageId } = buildMimeMessage({
      from: resolved.from,
      to,
      subject: input.subject,
      text: input.text,
      html: input.html,
      replyTo: input.replyTo,
    });
    await smtpSend(
      {
        host: resolved.smtp.host,
        port: resolved.smtp.port,
        security: resolved.smtp.security,
        username: resolved.smtp.username || undefined,
        password: resolved.smtp.password || undefined,
        timeoutMs: config.EMAIL_SEND_TIMEOUT_MS,
      },
      { from: resolved.fromAddress, to: to.map(bareAddress) },
      message,
    );
    await log('sent', null, messageId);
    return { ok: true, provider: 'smtp', messageId };
  } catch (err) {
    const error = (err as Error).message;
    await log('failed', error, null);
    return { ok: false, provider: resolved.provider, error };
  }
}

// Admin "Test connection": send a self-addressed probe (or to the address the
// admin typed) and stamp the outcome on the connection row.
export async function testEmailConnection(toOverride: string | null, tenantId = 'default'): Promise<SendEmailResult> {
  const resolved = await resolveSendConfig(tenantId);
  const to = toOverride || resolved.fromAddress;
  const result = await sendEmail({
    to,
    subject: 'ProxyPilot email test',
    text: 'This is a test message from your application’s email configuration. If you can read this, outbound email works.',
    tenantId,
  });
  await setConnectionTestResult(tenantId, result.ok, result.ok ? null : result.error ?? 'send failed');
  return result;
}

import { Router, type Request, type Response } from 'express';
import { z } from 'zod';
import { config } from './context.js';
import { EMAIL_PROVIDERS, SMTP_SECURITY_MODES } from './config.js';
import { encryptSecret } from './crypto.js';
import { getConnection, upsertConnection, listLog } from './repo.js';
import { resolveSendConfig, testEmailConnection } from './service.js';
import { isEmailAddress } from './mime.js';

// Admin router for the email module. MOUNT BEHIND YOUR ADMIN GUARD — e.g.
//   app.use('/api/admin/email', requirePermission('admin.settings'), adminEmailRoutes)
// The router itself performs no authentication (same posture as the auth
// module's adminAuthRoutes). Secrets are WRITE-ONLY: reads never return the
// stored key/password, only whether one exists.

const router = Router();

const saveSchema = z.object({
  provider: z.enum(EMAIL_PROVIDERS),
  from_email: z.string().trim().max(320),
  from_name: z.string().trim().max(120).default(''),
  smtp_host: z.string().trim().max(255).default(''),
  smtp_port: z.coerce.number().int().positive().max(65535).default(587),
  smtp_security: z.enum(SMTP_SECURITY_MODES).default('starttls'),
  smtp_username: z.string().trim().max(255).default(''),
  // The provider secret (Resend API key or SMTP password). Omitted/undefined →
  // keep the stored one; '' → clear; value → replace (encrypted at rest).
  secret: z.string().max(2000).optional(),
});

// GET / — the saved connection (redacted) + what would actually send right now
// (the env fallback shows through when nothing is configured).
router.get('/', async (_req: Request, res: Response) => {
  const conn = await getConnection();
  const effective = await resolveSendConfig();
  res.json({
    connection: conn
      ? {
          provider: conn.provider,
          from_email: conn.fromEmail,
          from_name: conn.fromName,
          smtp_host: conn.smtpHost,
          smtp_port: conn.smtpPort,
          smtp_security: conn.smtpSecurity,
          smtp_username: conn.smtpUsername,
          has_secret: !!conn.secretCiphertext,
          status: conn.status,
          last_test_at: conn.lastTestAt,
          last_test_error: conn.lastTestError,
        }
      : null,
    effective: { provider: effective.provider, from: effective.from },
  });
});

// PUT / — save the connection. Validates per provider, encrypts the secret.
router.put('/', async (req: Request, res: Response) => {
  const parsed = saveSchema.safeParse(req.body ?? {});
  if (!parsed.success) {
    return res.status(400).json({ error: parsed.error.issues[0]?.message ?? 'invalid configuration' });
  }
  const d = parsed.data;
  if (d.provider !== 'console' && !isEmailAddress(d.from_email)) {
    return res.status(400).json({ error: 'from_email must be a valid address' });
  }
  if (d.provider === 'smtp' && !d.smtp_host) {
    return res.status(400).json({ error: 'smtp_host is required for the smtp provider' });
  }
  const existing = await getConnection();
  if (d.provider === 'resend' && d.secret === undefined && !existing?.secretCiphertext) {
    return res.status(400).json({ error: 'a Resend API key is required (secret)' });
  }

  let secretCiphertext: string | null = null; // null → keep stored
  let secretNonce: string | null = null;
  if (d.secret !== undefined) {
    if (d.secret === '') {
      secretCiphertext = '';
      secretNonce = '';
    } else {
      const enc = encryptSecret(d.secret, config.EMAIL_MASTER_SECRET);
      secretCiphertext = enc.ciphertext;
      secretNonce = enc.nonce;
    }
  }

  const saved = await upsertConnection({
    provider: d.provider,
    fromEmail: d.from_email,
    fromName: d.from_name,
    smtpHost: d.smtp_host,
    smtpPort: d.smtp_port,
    smtpSecurity: d.smtp_security,
    smtpUsername: d.smtp_username,
    secretCiphertext,
    secretNonce,
    status: 'configured',
  });
  res.json({ ok: true, status: saved.status });
});

// POST /test — send a probe (to the given address, else self-addressed) and
// stamp the outcome on the connection row.
router.post('/test', async (req: Request, res: Response) => {
  const to = typeof req.body?.to === 'string' && req.body.to.trim() ? String(req.body.to).trim() : null;
  if (to && !isEmailAddress(to)) return res.status(400).json({ error: 'invalid test recipient' });
  const result = await testEmailConnection(to);
  res.status(result.ok ? 200 : 502).json(result);
});

// GET /log — recent sends (no bodies), newest first.
router.get('/log', async (req: Request, res: Response) => {
  const limit = Number(req.query.limit) || 100;
  const rows = await listLog('default', limit);
  res.json({
    entries: rows.map((r) => ({
      id: r.id,
      to: r.toEmail,
      subject: r.subject,
      provider: r.provider,
      status: r.status,
      error: r.error,
      message_id: r.messageId,
      created_at: r.createdAt,
    })),
  });
});

export default router;

