// Pure-layer tests: SMTP reply parsing, MIME building, dot-stuffing, secret
// round-trip, config defaults. No sockets, no DB.

describe('parseSmtpReply', () => {
  it('parses a single-line reply and leaves the rest', () => {
    const r = parseSmtpReply('250 OK\r\n354 go\r\n');
    expect(r).toEqual({ code: 250, text: '250 OK', rest: '354 go\r\n' });
  });
  it('accumulates multi-line replies to the final space line', () => {
    const r = parseSmtpReply('250-x.example STARTTLS\r\n250-AUTH PLAIN LOGIN\r\n250 SIZE 35882577\r\n');
    expect(r?.code).toBe(250);
    expect(r?.text).toContain('STARTTLS');
    expect(r?.rest).toBe('');
  });
  it('returns null while the reply is incomplete', () => {
    expect(parseSmtpReply('250-partial\r\n')).toBeNull();
    expect(parseSmtpReply('250 no terminator yet')).toBeNull();
  });
});

describe('mime', () => {
  it('extracts bare addresses and validates them', () => {
    expect(bareAddress('Jane Doe <jane@example.com>')).toBe('jane@example.com');
    expect(bareAddress('jane@example.com')).toBe('jane@example.com');
    expect(isEmailAddress('Jane <jane@example.com>')).toBe(true);
    expect(isEmailAddress('not-an-address')).toBe(false);
  });

  it('strips header injection and B-encodes non-ASCII', () => {
    expect(encodeHeaderValue('hi\r\nBcc: evil@x')).toBe('hi Bcc: evil@x');
    expect(encodeHeaderValue('héllo')).toMatch(/^=\?UTF-8\?B\?/);
  });

  it('builds multipart/alternative when both text and html are present', () => {
    const { message, messageId } = buildMimeMessage({
      from: 'App <app@example.com>',
      to: ['user@example.com'],
      subject: 'Verify your account',
      text: 'plain',
      html: '<b>rich</b>',
    });
    expect(message).toContain('multipart/alternative');
    expect(message).toContain('Content-Type: text/plain');
    expect(message).toContain('Content-Type: text/html');
    expect(message).toContain(`Message-ID: ${messageId}`);
    // CRLF discipline: no bare LF lines.
    expect(message.split('\r\n').some((l) => l.includes('\n'))).toBe(false);
  });

  it('dot-stuffs lines starting with a period', () => {
    expect(dotStuff('.leading\r\n.dot\r\nok')).toBe('..leading\r\n..dot\r\nok');
  });
});

describe('crypto', () => {
  it('round-trips a secret and fails on a wrong key', () => {
    const { ciphertext, nonce } = encryptSecret('re_123_secret', 'master-a');
    expect(decryptSecret(ciphertext, nonce, 'master-a')).toBe('re_123_secret');
    expect(() => decryptSecret(ciphertext, nonce, 'master-b')).toThrow();
  });
});

describe('config', () => {
  it('defaults to the console provider so an unconfigured app still boots', () => {
    const c = resolveEmailConfig({});
    expect(c.EMAIL_PROVIDER).toBe('console');
    expect(c.SMTP_PORT).toBe(587);
    expect(c.SMTP_SECURITY).toBe('starttls');
  });
  it('coerces and validates provider values', () => {
    expect(resolveEmailConfig({ EMAIL_PROVIDER: 'resend', SMTP_PORT: '465' }).SMTP_PORT).toBe(465);
    expect(() => resolveEmailConfig({ EMAIL_PROVIDER: 'sendgrid' })).toThrow();
  });
});
